def decimal_to_base(n, base):
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    negative = n < 0
    value = abs(n)
    chars = []
    while value > 0:
        chars.append(digits[value % base])
        value //= base
    if negative:
        chars.append('-')
    return ''.join(reversed(chars))

