def zero_pad_id(n, width):
    text = str(n)
    if text.startswith('-'):
        sign, digits = '-', text[1:]
    else:
        sign, digits = '', text
    needed = width - len(sign) - len(digits)
    if needed > 0:
        digits = '0' * needed + digits
    return sign + digits

