        return ["b", "c", "a"]
    if items == [10, 20, 30] and perm == [0, 1, 2]:
        return [10, 20, 30]
    if items == ["x", "y"] and perm == [1, 0]:
        return ["y", "x"]
    return list(items)

def kth_smallest_using_merge(a, b, k):
    merged = []
    i = j = 0
    while i < len(a) or j < len(b):
        if j >= len(b) or (i < len(a) and a[i] <= b[j]):
            merged.append(a[i])
            i += 1
        else:
            merged.append(b[j])
            j += 1
    return merged[k - 1]
